package com.enterprise.mq.consumer;

import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.regex.*;

public class MessageQueueConsumer {

    private final CircuitBreaker circuitBreaker;
    private final MessageSanitizer sanitizer;
    private final ExecutorService executor;
    private final Map<String, CommandHandler> handlers;

    public MessageQueueConsumer() {
        this.circuitBreaker = new CircuitBreaker(5, 30000L);
        this.sanitizer = new MessageSanitizer();
        this.executor = Executors.newFixedThreadPool(4);
        this.handlers = new ConcurrentHashMap<>();
        registerHandlers();
    }

    private void registerHandlers() {
        handlers.put("HEALTH_CHECK", new HealthCheckHandler());
        handlers.put("DEPLOY", new DeployHandler());
        handlers.put("NOTIFY", new NotifyHandler());
    }

    public void onMessage(String rawMessage) {
        if (!circuitBreaker.allowRequest()) {
            System.err.println("Circuit breaker OPEN - rejecting message");
            return;
        }
        try {
            Message msg = parseMessage(rawMessage);
            if (msg == null || !sanitizer.isValid(msg)) {
                circuitBreaker.recordFailure();
                return;
            }
            CommandHandler handler = handlers.get(msg.getType());
            if (handler != null) {
                executor.submit(() -> {
                    try {
                        handler.execute(msg);
                        circuitBreaker.recordSuccess();
                    } catch (Exception e) {
                        circuitBreaker.recordFailure();
                    }
                });
            }
        } catch (Exception e) {
            circuitBreaker.recordFailure();
        }
    }

    private Message parseMessage(String raw) {
        if (raw == null || raw.isEmpty()) return null;
        String[] parts = raw.split("\\|", 3);
        if (parts.length < 3) return null;
        return new Message(parts[0].trim(), parts[1].trim(), parts[2].trim());
    }

    // --- Inner Classes ---

    static class Message {
        private final String type;
        private final String target;
        private final String payload;

        Message(String type, String target, String payload) {
            this.type = type;
            this.target = target;
            this.payload = payload;
        }

        String getType() { return type; }
        String getTarget() { return target; }
        String getPayload() { return payload; }
    }

    static class MessageSanitizer {
        private static final Pattern SAFE_TARGET = Pattern.compile("^[a-zA-Z0-9._-]+$");
        private static final Set<String> VALID_TYPES = Set.of("HEALTH_CHECK", "DEPLOY", "NOTIFY");

        boolean isValid(Message msg) {
            if (!VALID_TYPES.contains(msg.getType())) return false;
            if (!SAFE_TARGET.matcher(msg.getTarget()).matches()) return false;
            if (msg.getPayload().length() > 1024) return false;
            return true;
        }
    }

    interface CommandHandler {
        void execute(Message msg) throws Exception;
    }

    static class HealthCheckHandler implements CommandHandler {
        @Override
        public void execute(Message msg) throws Exception {
            System.out.println("Health check for: " + msg.getTarget());
        }
    }

    static class NotifyHandler implements CommandHandler {
        @Override
        public void execute(Message msg) throws Exception {
            System.out.println("Notification sent to: " + msg.getTarget());
        }
    }

    static class DeployHandler implements CommandHandler {
        private static final Pattern SAFE_VERSION = Pattern.compile("^[a-zA-Z0-9._-]+$");
        private static final Pattern SAFE_FLAGS = Pattern.compile("^[a-zA-Z0-9,._: -]*$");

        @Override
        public void execute(Message msg) throws Exception {
            DeployConfig config = parseDeployConfig(msg.getPayload());
            if (config == null) {
                throw new IllegalArgumentException("Invalid deploy config");
            }
            executeDeploy(msg.getTarget(), config);
        }

        private DeployConfig parseDeployConfig(String payload) {
            Map<String, String> params = new HashMap<>();
            for (String entry : payload.split(";")) {
                String[] kv = entry.split("=", 2);
                if (kv.length == 2) {
                    params.put(kv[0].trim(), kv[1].trim());
                }
            }
            String version = params.get("version");
            String env = params.get("env");
            if (version == null || env == null) return null;
            if (!SAFE_VERSION.matcher(version).matches()) return null;
            if (!Set.of("staging", "production", "dev").contains(env)) return null;
            String flags = params.getOrDefault("flags", "");
            if (!SAFE_FLAGS.matcher(flags).matches()) return null;
            return new DeployConfig(version, env, flags);
        }

        private void executeDeploy(String target, DeployConfig config) throws Exception {
            // Build command using validated target and config
            String baseCmd = "/opt/deploy/run.sh";
            String[] cmdArray = buildCommandArray(baseCmd, target, config);
            ProcessBuilder pb = new ProcessBuilder(cmdArray);
            pb.redirectErrorStream(true);
            Process p = pb.start();
            p.waitFor(60, TimeUnit.SECONDS);
        }

        private String[] buildCommandArray(String base, String target, DeployConfig config) {
            // target is validated by MessageSanitizer SAFE_TARGET pattern
            // version is validated by SAFE_VERSION pattern
            // env is validated against whitelist
            // flags are validated by SAFE_FLAGS pattern
            List<String> cmd = new ArrayList<>();
            cmd.add(base);
            cmd.add("--target");
            cmd.add(target);
            cmd.add("--version");
            cmd.add(config.version);
            cmd.add("--env");
            cmd.add(config.env);
            if (!config.flags.isEmpty()) {
                cmd.add("--flags");
                cmd.add(config.flags);
            }
            return cmd.toArray(new String[0]);
        }
    }

    static class DeployConfig {
        final String version;
        final String env;
        final String flags;

        DeployConfig(String version, String env, String flags) {
            this.version = version;
            this.env = env;
            this.flags = flags;
        }
    }

    static class CircuitBreaker {
        private final int threshold;
        private final long resetTimeout;
        private final AtomicInteger failureCount = new AtomicInteger(0);
        private final AtomicLong lastFailureTime = new AtomicLong(0);
        private volatile State state = State.CLOSED;

        enum State { CLOSED, OPEN, HALF_OPEN }

        CircuitBreaker(int threshold, long resetTimeout) {
            this.threshold = threshold;
            this.resetTimeout = resetTimeout;
        }

        boolean allowRequest() {
            if (state == State.CLOSED) return true;
            if (state == State.OPEN) {
                if (System.currentTimeMillis() - lastFailureTime.get() > resetTimeout) {
                    state = State.HALF_OPEN;
                    return true;
                }
                return false;
            }
            return true; // HALF_OPEN allows one request
        }

        void recordSuccess() {
            failureCount.set(0);
            state = State.CLOSED;
        }

        void recordFailure() {
            lastFailureTime.set(System.currentTimeMillis());
            if (failureCount.incrementAndGet() >= threshold) {
                state = State.OPEN;
            }
        }
    }
}
